def find_boxes(g):
    H=len(g); W=len(g[0]); seen=set(); res=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==3 or (r,c) in seen: continue
            # expand max rectangle of border color v (border cells all v)
            # find maximal r1,c1 such that border all v
            best=None
            for r1 in range(r,H):
                for c1 in range(c,W):
                    border = all(g[r][cc]==v for cc in range(c,c1+1)) and all(g[r1][cc]==v for cc in range(c,c1+1)) and all(g[rr][c]==v for rr in range(r,r1+1)) and all(g[rr][c1]==v for rr in range(r,r1+1))
